<?php
namespace App\Http\Controllers\Admin;use App\Http\Controllers\Controller;use App\Models\{Conversation,Message};use Illuminate\Http\Request;
class ConversationController extends Controller{public function index(){return view('admin.chat.index',['conversations'=>Conversation::with(['messages'=>fn($q)=>$q->latest()->limit(1)])->orderByDesc('last_message_at')->paginate(30)]);}public function show(Conversation $conversation){return view('admin.chat.show',['conversation'=>$conversation->load(['messages'=>fn($q)=>$q->orderBy('created_at')])]);}public function reply(Request $request,Conversation $conversation){$data=$request->validate(['body'=>['required','string','max:2000']]);Message::create(['conversation_id'=>$conversation->id,'user_id'=>$request->user()->id,'sender_type'=>'staff','body'=>$data['body']]);$conversation->update(['last_message_at'=>now()]);return back()->with('status','Reply sent.');}}
